726		mustParseContext(t, `{"a":"�","b":"\u`+`FFFD"}`)
727		if got := eval(t, cfgLit, "f", `{"emoji":"�"}`); got.Reason != EvalDefault {
728			t.Fatalf("U+FFFD is just another string: %+v", got)
729		}
730		// 反斜杠转义后的 "\uD800" 是普通文本（内容为 \uD800 六个字符）。
731		mustParseContext(t, `{"a":"\\uD800"}`)
732		cfgText := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
733			{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\\uD800"}]}]}]}`
734		if got := eval(t, cfgText, "f", `{"a":"\\uD800"}`); got.Reason != EvalRule {
735			t.Fatalf("escaped backslash text: %+v", got)
736		}
737	}
738	
739	func TestEmptyFlagListAndFind(t *testing.T) {
