// 写法（1e400、-1e400、400 位整数）都要按原文保留并命中。
func TestQuotedBigNumberIsOrdinaryString(t *testing.T) {
	hugeInt := "1" + strings.Repeat("0", 400)
	for _, tc := range []struct {
		text string
	}{
		{"1e400", "1e400"},
		{"-1e400", "-1e400"},
